import React from 'react';
import './MovieCategories.css';
import Icon from './Icon';

function MovieCategories({ genres, selectedGenre, onSelectGenre }) {
  const genreIcons = {
    'Tất cả': <Icon name="sparkle" size={20} className="genre-icon" />,
    'Hoạt Hình': <Icon name="star" size={20} className="genre-icon" />,
    'Hành Động': <Icon name="flame" size={20} animation="flame" className="genre-icon" />,
    'Viễn Tưởng': <Icon name="sparkle" size={20} animation="rotate" className="genre-icon" />,
    'Kinh Dị': <Icon name="film" size={20} className="genre-icon" />,
    'Tình Cảm': <Icon name="heart" size={20} animation="heartbeat" className="genre-icon" />,
    'Hài Kịch': <Icon name="smile" size={20} className="genre-icon" />,
    'Tâm Lý': <Icon name="search" size={20} className="genre-icon" />,
    'Dạo Mạo': <Icon name="play" size={20} className="genre-icon" />,
    'Trinh Thám': <Icon name="shield" size={20} className="genre-icon" />,
    'Gia đình': <Icon name="heart" size={20} className="genre-icon" />,
    'Sử thi': <Icon name="shield" size={20} className="genre-icon" />
  };

  return (
    <section className="movie-categories">
      <h2>Khám Phá Thể Loại</h2>
      <p className="genre-subtitle">Chọn thể loại phù hợp với tâm trạng và kéo ngay xuống phần phim để chọn tiếp.</p>
      <div className="categories-list">
        {genres.map((genre) => (
          <button
            key={genre}
            className={`category-button ${selectedGenre === genre ? 'active' : ''}`}
            onClick={() => onSelectGenre(genre)}
          >
            <span className="genre-emoji">{genreIcons[genre] || <Icon name="sparkle" size={20} className="genre-icon" />}</span>
            <span className="genre-name">{genre}</span>
          </button>
        ))}
      </div>
    </section>
  );
}

export default MovieCategories;
